INSERT INTO lojas (id, usuario_id, nome, slug, descricao, cidade, uf, cor, criado_em) VALUES
(1, 3, 'Ateliê Jacarandá', 'atelie-jacaranda', 'Ateliê de decoração afetiva: luminárias, velas artesanais e plantas que deixam a casa com cara de lar.', 'Belo Horizonte', 'MG', '#B4532A', DATE_SUB(NOW(), INTERVAL 452160 MINUTE)),
(2, 4, 'Pixel Paraná', 'pixel-parana', 'Tecnologia escolhida a dedo por quem testa tudo antes de vender. Áudio, vestíveis e câmeras.', 'Curitiba', 'PR', '#2563A8', DATE_SUB(NOW(), INTERVAL 444960 MINUTE)),
(3, 5, 'Nível Up Games', 'nivel-up-games', 'Setups gamer montados com carinho no coração da Amazônia. Teclados mecânicos e controles.', 'Manaus', 'AM', '#6D28D9', DATE_SUB(NOW(), INTERVAL 437760 MINUTE)),
(4, 6, 'Vento Sul Moda', 'vento-sul-moda', 'Moda urbana confortável, produzida em pequenas tiragens no Sul do Brasil.', 'Porto Alegre', 'RS', '#0F766E', DATE_SUB(NOW(), INTERVAL 264960 MINUTE)),
(5, 7, 'Cerrado Couros', 'cerrado-couros', 'Couro legítimo curtido no Cerrado e costurado à mão. Peças que envelhecem bonito.', 'Goiânia', 'GO', '#8A4B1F', DATE_SUB(NOW(), INTERVAL 257760 MINUTE)),
(6, 8, 'Ouro de Minas', 'ouro-de-minas', 'Joias banhadas a ouro e acessórios clássicos, com o brilho das Gerais.', 'Ouro Preto', 'MG', '#B7791F', DATE_SUB(NOW(), INTERVAL 413280 MINUTE)),
(7, 9, 'Torra Fina Café', 'torra-fina-cafe', 'Torrefação artesanal e utensílios para quem leva o café a sério.', 'Poços de Caldas', 'MG', '#7C4A2D', DATE_SUB(NOW(), INTERVAL 228960 MINUTE)),
(8, 10, 'Bela Raiz Cosméticos', 'bela-raiz-cosmeticos', 'Cosmética natural com ativos brasileiros, sem testes em animais.', 'Salvador', 'BA', '#BE185D', DATE_SUB(NOW(), INTERVAL 545760 MINUTE)),
(9, 11, 'Pedal & Trilha', 'pedal-e-trilha', 'Equipamentos para treinar em casa, correr na praia e cuidar do corpo.', 'Florianópolis', 'SC', '#15803D', DATE_SUB(NOW(), INTERVAL 213120 MINUTE)),
(10, 12, 'Casa Pet Amora', 'casa-pet-amora', 'Produtos pensados por tutores, testados pela Amora — nossa gata gerente.', 'Recife', 'PE', '#DB2777', DATE_SUB(NOW(), INTERVAL 230400 MINUTE)),
(11, 13, 'Papel & Prosa', 'papel-e-prosa', 'Papelaria autoral e curadoria de livros para quem gosta de anotar a vida.', 'São Paulo', 'SP', '#1E3A8A', DATE_SUB(NOW(), INTERVAL 296640 MINUTE));
INSERT INTO produtos (id, vendedor_id, categoria_id, nome, descricao, preco, preco_original, estoque, imagem, destaque, frete_gratis, criado_em) VALUES
(1, 4, 1, 'Fone Over-ear Bluetooth Aura', 'Fone sem fio com almofadas de espuma viscoelástica e até 40 horas de bateria. Graves encorpados sem abafar a voz, conexão Bluetooth estável e dobradiças que cabem em qualquer mochila.', 349.90, 429.90, 24, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 95040 MINUTE)),
(2, 4, 1, 'Fone Retrô com Fio Studio', 'Design de estúdio dos anos 70 com som atual. Cabo trançado de 1,5 m, conchas de alumínio escovado e couro sintético macio para longas sessões.', 189.90, NULL, 15, 'https://images.unsplash.com/photo-1484704849700-f032a568e944?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 164160 MINUTE)),
(3, 4, 1, 'Headphone Creme com Cancelamento de Ruído', 'Cancelamento de ruído ativo em três níveis, modo ambiente e microfones para chamadas nítidas. Acabamento creme fosco que combina com tudo.', 599.90, 749.90, 8, 'https://images.unsplash.com/photo-1766338055584-5ffe426a7e57?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 182880 MINUTE)),
(4, 4, 1, 'Caixa de Som Portátil Pulse', 'Som 360° com 20 W, resistência a respingos e 12 horas de festa. Pareie duas unidades para tocar em estéreo.', 259.90, 299.90, 30, 'https://images.unsplash.com/photo-1582978571763-2d039e56f0c3?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 120960 MINUTE)),
(5, 4, 1, 'Caixa de Som Mineral Oval', 'Formato de seixo, tecido acústico cinza e graves surpreendentes para o tamanho. Fica bonita na estante e cabe na palma da mão.', 219.90, NULL, 12, 'https://images.unsplash.com/photo-1547052178-7f2c5a20c332?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 197280 MINUTE)),
(6, 4, 1, 'Smartwatch Fit Pro', 'Tela AMOLED sempre ativa, monitor cardíaco, oxigenação do sangue, GPS integrado e mais de 100 modos de treino. Até 10 dias de bateria.', 449.90, 549.90, 20, 'https://images.unsplash.com/photo-1553545204-4f7d339aa06a?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 126720 MINUTE)),
(7, 4, 1, 'Câmera Instantânea Memória', 'Fotos reveladas na hora para guardar na carteira ou colar na geladeira. Flash automático, espelho de selfie e modo close-up.', 459.90, NULL, 9, 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 99360 MINUTE)),
(8, 4, 1, 'Fone Bluetooth Candy Rosa', 'Leve, colorido e com 30 horas de reprodução. Arco ajustável, controles por toque e estojo de tecido incluso.', 279.90, NULL, 14, 'https://images.unsplash.com/photo-1613040809024-b4ef7ba99bc3?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 194400 MINUTE)),
(9, 5, 2, 'Teclado Mecânico Âmbar Edition', 'Teclas PBT em preto e laranja, switches táteis lubrificados de fábrica e hot-swap para trocar sem solda. Edição em parceria com a curadoria Âmbar.', 529.90, 649.90, 18, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 152640 MINUTE)),
(10, 5, 2, 'Teclado Mecânico Pastel 65%', 'Layout compacto de 65%, keycaps em tons pastel e conexão com fio, Bluetooth ou 2.4 GHz. Mesa organizada, digitação macia.', 459.90, NULL, 10, 'https://images.unsplash.com/photo-1595044426077-d36d9236d54a?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 86400 MINUTE)),
(11, 5, 2, 'Controle Sem Fio Neon', 'Gatilhos com resposta progressiva, vibração dupla e iluminação neon personalizável. Compatível com PC, Android e consoles.', 329.90, NULL, 25, 'https://images.unsplash.com/photo-1612287230202-1ff1d85d1bdf?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 132480 MINUTE)),
(12, 5, 2, 'Controle Pro Branco', 'Botões traseiros programáveis, analógicos com sensor Hall que não sofrem drift e bateria para 30 horas.', 349.90, 399.90, 0, 'https://images.unsplash.com/photo-1774105416183-5058512ec5f0?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 144000 MINUTE)),
(13, 5, 2, 'Teclado Gamer RGB Switch Vermelho', 'Switches lineares vermelhos para respostas rápidas, iluminação RGB por tecla e apoio de punho magnético.', 389.90, NULL, 7, 'https://images.unsplash.com/photo-1635987391914-cb84b567e68f?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 47520 MINUTE)),
(14, 5, 2, 'Kit Setup Controle e Base', 'Controle com fio de 3 m e base de carregamento com iluminação ambiente. Deixa o setup pronto para as noites de jogo.', 299.90, NULL, 11, 'https://images.unsplash.com/photo-1552820728-8b83bb6b773f?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 86400 MINUTE)),
(15, 6, 3, 'Tênis Casual Pastel', 'Cabedal em camurça sintética nas cores lilás, menta e rosa. Palmilha de látex reciclado e solado de borracha natural.', 289.90, 349.90, 22, 'https://images.unsplash.com/photo-1595950653106-6c9ebd614d3a?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 109440 MINUTE)),
(16, 6, 3, 'Tênis Branco Minimal', 'O tênis branco que combina com tudo. Couro sintético premium, costura reforçada e forro respirável.', 319.90, NULL, 17, 'https://images.unsplash.com/photo-1600269452121-4f2416e55c28?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 109440 MINUTE)),
(17, 6, 3, 'Tênis de Lona Bordô', 'Clássico de lona grossa em bordô profundo, biqueira de borracha e cadarço de algodão. Fica ainda melhor com o tempo.', 169.90, NULL, 26, 'https://images.unsplash.com/photo-1525966222134-fcfa99b8ae77?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 131040 MINUTE)),
(18, 6, 3, 'Jaqueta Jeans Clássica', 'Denim 100% algodão com lavagem média, botões de metal e bolsos frontais com lapela. Modelagem levemente oversized.', 279.90, NULL, 19, 'https://images.unsplash.com/photo-1611312449408-fcece27cdbb7?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 154080 MINUTE)),
(19, 6, 3, 'Boné Branco Essencial', 'Sarja de algodão lavada, aba curva e fecho ajustável de metal. Simples do jeito certo.', 79.90, NULL, 40, 'https://images.unsplash.com/photo-1691256676359-20e5c6d4bc92?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 191520 MINUTE)),
(20, 6, 3, 'Tênis Perfurado Premium', 'Couro com painéis perfurados para ventilação, entressola de EVA injetado e acabamento costurado à mão.', 459.90, NULL, 9, 'https://images.unsplash.com/photo-1608231387042-66d1773070a5?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 192960 MINUTE)),
(21, 7, 4, 'Bolsa de Couro Caramelo', 'Couro legítimo em tom caramelo, alça de mão e alça transversal removível. Forro de algodão e bolso interno com zíper.', 389.90, 459.90, 12, 'https://images.unsplash.com/photo-1598532163257-ae3c6b2524b6?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 56160 MINUTE)),
(22, 7, 4, 'Bolsa Transversal Sela', 'Formato de meia-lua inspirado em selas de montaria. Compacta, cabe celular, carteira e chaves.', 249.90, NULL, 16, 'https://images.unsplash.com/photo-1600857062241-98e5dba7f214?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 69120 MINUTE)),
(23, 7, 4, 'Bolsa Satchel Grafite', 'Couro grafite com fivelas douradas e fundo estruturado. Elegante para o trabalho e espaçosa para o fim de semana.', 429.90, NULL, 6, 'https://images.unsplash.com/photo-1605733513597-a8f8341084e6?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 108000 MINUTE)),
(24, 7, 4, 'Mochila de Couro Rubi', 'Couro vermelho-rubi, compartimento acolchoado para notebook de até 14" e alças com regulagem.', 499.90, NULL, 5, 'https://images.unsplash.com/photo-1622560480654-d96214fdc887?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 201600 MINUTE)),
(25, 7, 4, 'Carteira de Couro Bifold', 'Seis divisórias para cartões, compartimento para notas e costura encerada à mão. Fina no bolso, forte no uso.', 129.90, 159.90, 35, 'https://images.unsplash.com/photo-1601592996763-f05c9c80a7f1?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 83520 MINUTE)),
(26, 7, 4, 'Mala Duffel de Couro Preta', 'Para viagens curtas: 35 litros, base reforçada, alça de ombro acolchoada e compartimento para sapatos.', 549.90, NULL, 8, 'https://images.unsplash.com/photo-1758542988969-39a10168b2ce?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 115200 MINUTE)),
(27, 7, 4, 'Mochila Urbana Lona e Couro', 'Lona encerada resistente à água com detalhes em couro. Leve, com espaço para tudo o que faz parte da sua rotina.', 189.90, NULL, 24, 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 171360 MINUTE)),
(28, 8, 5, 'Relógio Minimalista Couro', 'Mostrador limpo, caixa de aço de 40 mm e pulseira de couro legítimo. Resistente a respingos.', 229.90, NULL, 12, 'https://images.unsplash.com/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 152640 MINUTE)),
(29, 8, 5, 'Colar Corrente Dourada', 'Corrente cartier banhada a ouro 18k com fecho lagosta. Hipoalergênica e com garantia de um ano.', 189.90, NULL, 18, 'https://images.unsplash.com/photo-1611107683227-e9060eccd846?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 108000 MINUTE)),
(30, 8, 5, 'Colar Pingente Círculo', 'Delicado pingente circular em corrente veneziana. Para usar sozinho ou em camadas.', 159.90, 199.90, 21, 'https://images.unsplash.com/photo-1773929345739-94db8a4ccd0c?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 214560 MINUTE)),
(31, 8, 5, 'Colar Dourado Pingente Oval', 'Pingente oval martelado à mão em Ouro Preto. Cada peça tem um brilho único.', 219.90, NULL, 7, 'https://images.unsplash.com/photo-1783541507490-edb026e2a961?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 103680 MINUTE)),
(32, 8, 5, 'Óculos de Sol Clássico', 'Armação leve de acetato, lentes com proteção UV400 e personalidade nos pequenos detalhes.', 129.90, NULL, 14, 'https://images.unsplash.com/photo-1511499767150-a48a237f0083?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 77760 MINUTE)),
(33, 8, 5, 'Óculos Tartaruga Vintage', 'Estilo clubmaster com acetato tartaruga e hastes metálicas douradas. Acompanha estojo de couro.', 149.90, NULL, 10, 'https://images.unsplash.com/photo-1537832816519-689ad163238b?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 84960 MINUTE)),
(34, 3, 6, 'Luminária de Mesa Âmbar', 'Cúpula de vidro âmbar e base de madeira torneada. Luz quente e acolhedora para o seu canto de leitura.', 159.90, 189.90, 7, 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 141120 MINUTE)),
(35, 3, 6, 'Vela Aromática Copo de Vidro', 'Cera vegetal de coco, pavio de algodão e notas de lavanda com cedro. Cerca de 40 horas de queima.', 69.90, NULL, 40, 'https://images.unsplash.com/photo-1602874801007-bd458bb1b8b6?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 102240 MINUTE)),
(36, 3, 6, 'Vela Âmbar e Baunilha', 'Assinatura da casa: âmbar, baunilha e um toque de cravo. Feita à mão em pequenos lotes.', 89.90, NULL, 28, 'https://images.unsplash.com/photo-1669334388727-9a3437e12fa2?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 125280 MINUTE)),
(37, 3, 6, 'Planta em Vaso de Cerâmica', 'Planta de folhagem fácil de cuidar em vaso de cerâmica esmaltada feita por artesãos de Minas.', 119.90, NULL, 15, 'https://images.unsplash.com/photo-1609061801093-1b7a8a574c69?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 92160 MINUTE)),
(38, 3, 6, 'Vaso de Barro com Planta', 'Barro cozido em forno a lenha, com prato coletor. A planta chega aclimatada e pronta para a sua sala.', 99.90, NULL, 11, 'https://images.unsplash.com/photo-1592064465579-6796bfdaa5cd?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 136800 MINUTE)),
(39, 3, 6, 'Poltrona de Couro Conhaque', 'Estrutura de madeira maciça e couro conhaque que ganha pátina com o uso. Montada e entregue pronta.', 1299.90, 1499.90, 4, 'https://images.unsplash.com/photo-1601366533287-5ee4c763ae4e?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 203040 MINUTE)),
(40, 3, 6, 'Almofada de Linho Natural', 'Capa de linho lavado com zíper invisível e enchimento de fibra siliconada. 45 × 45 cm.', 79.90, NULL, 33, 'https://images.unsplash.com/photo-1558897010-6732ac419cd1?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 223200 MINUTE)),
(41, 3, 6, 'Poltrona Escandinava de Madeira', 'Linhas retas, madeira de reflorestamento e assento estofado. Conforto nórdico com mão de obra mineira.', 899.90, NULL, 3, 'https://images.unsplash.com/photo-1605702098590-d552a98dc93d?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 178560 MINUTE)),
(42, 9, 7, 'Caneca de Cerâmica Artesanal', 'Torneada à mão e esmaltada em tons terrosos. 300 ml, vai ao micro-ondas e à lava-louças.', 59.90, NULL, 50, 'https://images.unsplash.com/photo-1595670322505-4de61b9cdf47?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 84960 MINUTE)),
(43, 9, 7, 'Garrafa Térmica Inox 1 L', 'Parede dupla de aço inox: bebidas quentes por 12 horas e geladas por 24. Tampa com trava antivazamento.', 89.90, NULL, 32, 'https://images.unsplash.com/photo-1602143407151-7111542de6e8?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 92160 MINUTE)),
(44, 9, 7, 'Cafeteira de Vidro Pour Over', 'Vidro borossilicato com colar de madeira e filtro reutilizável. O café mais limpo e aromático em 4 minutos.', 149.90, NULL, 14, 'https://images.unsplash.com/photo-1610874150308-a1e6f8c905d9?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 167040 MINUTE)),
(45, 9, 7, 'Frigideira de Ferro Fundido 26 cm', 'Pré-curada com óleo vegetal, vai do fogão ao forno e dura gerações. Retém o calor como nenhuma outra.', 219.90, 259.90, 10, 'https://images.unsplash.com/photo-1586524068358-77d2196875e7?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 162720 MINUTE)),
(46, 9, 7, 'Café Especial Torra Média 500 g', 'Grãos 100% arábica do Sul de Minas, notas de caramelo e chocolate ao leite. Torrado sob encomenda.', 54.90, NULL, 60, 'https://images.unsplash.com/photo-1541161284823-be8c6571a945?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 31680 MINUTE)),
(47, 9, 7, 'Máquina de Espresso Compacta', 'Bomba de 15 bar, vaporizador para leite e aquecimento em 30 segundos. Espresso de cafeteria na sua bancada.', 1199.90, 1399.90, 6, 'https://images.unsplash.com/photo-1553329701-1abe5e1bf403?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 181440 MINUTE)),
(48, 10, 8, 'Perfume Âmbar Noir 100 ml', 'Âmbar, baunilha negra e madeiras brasileiras. Eau de parfum de alta fixação, envasado em Salvador.', 289.90, 349.90, 20, 'https://images.unsplash.com/photo-1594035910387-fea47794261f?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 84960 MINUTE)),
(49, 10, 8, 'Perfume Floral Cristal 50 ml', 'Flor de laranjeira, jasmim e almíscar branco. Delicado para o dia, marcante à noite.', 219.90, NULL, 15, 'https://images.unsplash.com/photo-1761659760494-32b921a2449f?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 129600 MINUTE)),
(50, 10, 8, 'Sérum Facial Vitamina C', 'Vitamina C estabilizada a 10% com óleo de buriti. Ilumina, uniformiza o tom e protege contra a oxidação.', 129.90, NULL, 30, 'https://images.unsplash.com/photo-1608571423902-eed4a5ad8108?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 106560 MINUTE)),
(51, 10, 8, 'Kit Pincéis de Maquiagem', 'Doze pincéis com cerdas sintéticas macias, cabo de bambu e necessaire de algodão cru.', 99.90, NULL, 25, 'https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 106560 MINUTE)),
(52, 10, 8, 'Kit Maquiagem Essencial', 'Base, corretivo, blush e máscara em tons que valorizam a pele brasileira. Vegano e cruelty-free.', 149.90, NULL, 18, 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 47520 MINUTE)),
(53, 10, 8, 'Kit Skincare Ritual Noturno', 'Óleo demaquilante, hidratante de manteiga de cupuaçu e bruma facial. Três passos para acordar com a pele renovada.', 199.90, 249.90, 9, 'https://images.unsplash.com/photo-1622618991746-fe6004db3a47?auto=format&fit=crop&w=900&q=80', FALSE, TRUE, DATE_SUB(NOW(), INTERVAL 38880 MINUTE)),
(54, 11, 9, 'Tapete de Yoga com Blocos', 'Tapete de borracha natural de 5 mm com dois blocos de cortiça. Aderência firme, mesmo no suor.', 169.90, NULL, 21, 'https://images.unsplash.com/photo-1646239646963-b0b9be56d6b5?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 96480 MINUTE)),
(55, 11, 9, 'Par de Halteres 5 kg', 'Revestimento emborrachado que não risca o piso e pegada antiderrapante. Vendido em par.', 139.90, NULL, 16, 'https://images.unsplash.com/photo-1638536534984-0d98ccdb6af5?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 128160 MINUTE)),
(56, 11, 9, 'Tênis de Corrida Laranja', 'Entressola responsiva, cabedal em malha respirável e solado com tração para asfalto e areia batida.', 399.90, 459.90, 13, 'https://images.unsplash.com/photo-1560769629-975ec94e6a86?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 54720 MINUTE)),
(57, 11, 9, 'Halter Emborrachado Rosa 2 kg', 'Ideal para treinos funcionais e reabilitação. Formato hexagonal que não rola.', 59.90, NULL, 30, 'https://images.unsplash.com/photo-1591291621164-2c6367723315?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 83520 MINUTE)),
(58, 11, 9, 'Tênis Running Branco e Laranja', 'Leve como deve ser: 230 g, drop de 8 mm e placa de estabilidade no médio-pé para longas distâncias.', 429.90, NULL, 12, 'https://images.unsplash.com/photo-1600185365926-3a2ce3cdb9eb?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 158400 MINUTE)),
(59, 11, 9, 'Kit Dois Tapetes Antiderrapantes', 'Dois tapetes de TPE com alça de transporte. Perfeito para treinar em dupla.', 199.90, NULL, 8, 'https://images.unsplash.com/photo-1763004871583-4183d64096b1?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 151200 MINUTE)),
(60, 12, 10, 'Arranhador com Brinquedo de Pelúcia', 'Poste de sisal natural com base estável e peixinho de pelúcia pendurado. Aprovado pela Amora.', 149.90, NULL, 12, 'https://images.unsplash.com/photo-1545249390-6bdfa286032f?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 63360 MINUTE)),
(61, 12, 10, 'Varinha Interativa para Gatos', 'Haste flexível com plumas e guizo. Gasta a energia dos felinos mais agitados em minutos.', 39.90, NULL, 45, 'https://images.unsplash.com/photo-1768859336207-3c3ba2027cca?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 97920 MINUTE)),
(62, 12, 10, 'Coleira de Couro Ajustável', 'Couro legítimo com forro macio, fivela de inox e argola para plaquinha de identificação.', 69.90, NULL, 25, 'https://images.unsplash.com/photo-1738127918918-7589e808444c?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 184320 MINUTE)),
(63, 12, 10, 'Manta Protetora para Sofá', 'Tecido impermeável e lavável que protege o sofá dos pelos e das patinhas. 1,20 × 1,50 m.', 89.90, NULL, 20, 'https://images.unsplash.com/photo-1675962614159-2b62fc7d0007?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 44640 MINUTE)),
(64, 12, 10, 'Kit Laços e Presilhas Pet', 'Seis laços e presilhas de tecido em cores alegres para deixar o pet pronto para a foto.', 34.90, NULL, 30, 'https://images.unsplash.com/photo-1789846958535-075e099d3c4d?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 218880 MINUTE)),
(65, 13, 11, 'Caderno Pontilhado Capa Dura', '160 páginas de papel 120 g/m², pontilhado discreto e marcador de fita. Para listas, desenhos e ideias.', 49.90, NULL, 60, 'https://images.unsplash.com/photo-1611079830811-865ff4428d17?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 165600 MINUTE)),
(66, 13, 11, 'Planner Azul com Caneta', 'Planner não datado com visão mensal e semanal, capa de linho azul e caneta de gel inclusa.', 59.90, NULL, 40, 'https://images.unsplash.com/photo-1647559709298-c0e3dcb47092?auto=format&fit=crop&w=900&q=80', TRUE, FALSE, DATE_SUB(NOW(), INTERVAL 197280 MINUTE)),
(67, 13, 11, 'Kit Clássicos da Literatura', 'Cinco clássicos em edição de bolso escolhidos pela nossa curadoria. Uma estante inteira de boas histórias.', 149.90, 189.90, 15, 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=900&q=80', TRUE, TRUE, DATE_SUB(NOW(), INTERVAL 184320 MINUTE)),
(68, 13, 11, 'Caderno Espiral Kraft', 'Capa kraft resistente, 96 folhas pautadas e espiral duplo de metal. O companheiro de todas as aulas.', 34.90, NULL, 50, 'https://images.unsplash.com/photo-1531346878377-a5be20888e57?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 123840 MINUTE)),
(69, 13, 11, 'Box Leituras de Fim de Semana', 'Três romances curtos e envolventes para ler de sábado a domingo, com marcador artesanal de presente.', 119.90, NULL, 10, 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e?auto=format&fit=crop&w=900&q=80', FALSE, FALSE, DATE_SUB(NOW(), INTERVAL 74880 MINUTE));
