-- Totais derivados: vendidos, avaliações e usos de cupom
UPDATE produtos p SET total_vendido = (
    SELECT COALESCE(SUM(i.quantidade), 0) FROM pedido_itens i
    INNER JOIN pedidos o ON o.id = i.pedido_id
    WHERE i.produto_id = p.id AND o.status <> 'cancelado'
);
UPDATE produtos p SET
    avaliacao_media = COALESCE((SELECT ROUND(AVG(a.nota), 2) FROM avaliacoes a WHERE a.produto_id = p.id AND a.visivel = TRUE), 0),
    total_avaliacoes = (SELECT COUNT(*) FROM avaliacoes a WHERE a.produto_id = p.id AND a.visivel = TRUE);
UPDATE cupons c SET usos = (SELECT COUNT(*) FROM cupom_usos u WHERE u.cupom_id = c.id);

COMMIT;
